package com.gestordevendas.api.food; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/food") public class FoodController {private final FoodService s; public FoodController(FoodService s){this.s=s;} @GetMapping("/couriers") public List<CourierResponse> couriers(){return s.couriers();} @PostMapping("/couriers") public CourierResponse createCourier(@Valid @RequestBody CourierRequest r){return s.saveCourier(null,r);} @PutMapping("/couriers/{id}") public CourierResponse updateCourier(@PathVariable UUID id, @Valid @RequestBody CourierRequest r){return s.saveCourier(id,r);} @DeleteMapping("/couriers/{id}") public void deleteCourier(@PathVariable UUID id){s.deleteCourier(id);} @GetMapping("/couriers/report") public CourierReportResponse report(){return s.report();} @GetMapping("/snacks") public List<SnackResponse> snacks(){return s.snacks();} @PostMapping("/snacks") public SnackResponse createSnack(@Valid @RequestBody SnackRequest r){return s.saveSnack(null,r);} @PutMapping("/snacks/{id}") public SnackResponse updateSnack(@PathVariable UUID id, @Valid @RequestBody SnackRequest r){return s.saveSnack(id,r);} @DeleteMapping("/snacks/{id}") public void deleteSnack(@PathVariable UUID id){s.deleteSnack(id);} @GetMapping("/orders") public List<SnackOrderResponse> orders(){return s.orders();} @PostMapping("/orders") public SnackOrderResponse order(@Valid @RequestBody SnackOrderRequest r){return s.createOrder(r);} }